		["hunter-survival"] = {
			{ level = 10, lines = {
				{ spellId = 415336, name = "Raptor Strike", condition = "Raptor Strike queued on the swing timer (tag 3, the on-next-swing queue tag), gated at 20% mana so it does not starve Mongoose Bite below." },
			} },
			{ level = 20, lines = {
				{ spellId = 415337, name = "Raptor Strike", condition = "Raptor Strike queued on the swing timer (tag 3, the on-next-swing queue tag), gated at 20% mana so it does not starve Mongoose Bite below." },
				{ spellId = 1495, name = "Mongoose Bite", condition = "Mongoose Bite inside its window: the client allows it only after a dodge, and Expose Prey opens the same 5 second window (Defensive State, spell 5302) on a melee or ranged attack against a Hunter's Mark target; the window is one charge, spent by the cast." },
				{ spellId = 13795, name = "Immolation Trap", condition = "Immolation Trap on cooldown: within 5 yards it lands as a melee-range filler, gated only by its own 30-second cooldown and mana cost." },
				{ spellId = 2974, name = "Wing Clip", condition = "Wing Clip on every free global, only while a Windfury Totem reaches the hunter (the gate asks whether the engine registered the totem's attack power buff, spell 10610, so a character with no totem skips the line): a cheap main-hand special that rolls the totem's extra attack and any weapon proc, which the other lines leave idle." },
			} },
			{ level = 30, lines = {
				{ spellId = 415338, name = "Raptor Strike", condition = "Raptor Strike queued on the swing timer (tag 3, the on-next-swing queue tag), gated at 20% mana so it does not starve Mongoose Bite below." },
				{ spellId = 1242634, name = "Counterattack", condition = "Counterattack: a bare cast that only lands while its parry-triggered proc aura is active." },
				{ spellId = 14269, name = "Mongoose Bite", condition = "Mongoose Bite inside its window: the client allows it only after a dodge, and Expose Prey opens the same 5 second window (Defensive State, spell 5302) on a melee or ranged attack against a Hunter's Mark target; the window is one charge, spent by the cast." },
				{ spellId = 24118, name = "Lacerate", condition = "Lacerate (the trainable bleed, rank 4) whenever its own bleed is down: with Mongoose Bite waiting on its window, the free globals go to keeping the bleed ticking." },
				{ spellId = 1317257, name = "Strider Kick", condition = "Strider Kick as the lowest-priority filler on its own 8s cooldown." },
				{ spellId = 14302, name = "Immolation Trap", condition = "Immolation Trap on cooldown: within 5 yards it lands as a melee-range filler, gated only by its own 30-second cooldown and mana cost." },
				{ spellId = 2974, name = "Wing Clip", condition = "Wing Clip on every free global, only while a Windfury Totem reaches the hunter (the gate asks whether the engine registered the totem's attack power buff, spell 10610, so a character with no totem skips the line): a cheap main-hand special that rolls the totem's extra attack and any weapon proc, which the other lines leave idle." },
